/bin/zsh -lc "python3 -B -c 'import copy
import hashlib
import json
from pathlib import Path
from gateway import Gateway

vectors = json.loads(Path(\"requests.json\").read_text())
headers = vectors[0][\"headers\"]
body = vectors[0][\"body\"]

def read(gateway, caller, handle):
    request = copy.deepcopy(body)
    request[\"params\"][\"arguments\"] = {\"handle\": handle}
    try:
        outcome = gateway.call(headers, request, caller)
    except Exception as error:
        outcome = {\"error\": type(error).__name__, \"message\": str(error)}
    return {\"caller\": caller, \"handle\": handle, \"outcome\": outcome, \"dispatches\": gateway.dispatches}

for owner, outsider in [(\"alice\", \"bob\"), (\"bob\", \"alice\")]:
    gateway = Gateway()
    handle = \"h-\" + owner
    observations = [read(gateway, outsider, handle), read(gateway, owner, handle), read(gateway, outsider, handle)]
    print(json.dumps({\"schedule\": \"cold outsider, owner warms, warm outsider\", \"owner\": owner, \"observations\": observations}))
    print(json.dumps({\"schedule\": \"new gateway resets warm state\", \"observation\": read(Gateway(), outsider, handle)}))
print(json.dumps({\"candidate_sha256\": hashlib.sha256(Path(\"gateway.py\").read_bytes()).hexdigest()}))'"

